export type HierarchyItem = {
    id?: number;
    level: number;
    name: string;
    nestedId: string;
    subHierarchy: HierarchyItem[];
    disabled?: boolean;
    parentId?: number | null;
    selected?: boolean;
    upcCount?: number;
};
export type Filter = {
    nestedId: string;
    parentId?: number | null;
    level?: number;
    name?: string;
    parentNestedId?: string;
    upcCount?: number;
};
export type Filters = {
    valid: Filter[];
    invalid: Filter[];
    disabled: Filter[];
};
export type Selection = {
    name?: string;
    nestedId: string;
    selectedChildren?: Selection[];
};
export type HierarchySelectorItem = Omit<HierarchyItem, 'subHierarchy'> & {
    checked?: boolean;
    disabled?: boolean;
    indeterminate?: boolean;
    expanded?: boolean;
    showChildren?: boolean;
    subHierarchy: HierarchySelectorItem[];
    parentNestedId?: string;
};
export type LevelDataMap = Map<string, HierarchySelectorItem>;
